/**
 * POST /api/sky/solve/explain-stream
 *
 * Streaming version of the explain endpoint.
 * Uses SSE to emit steps, answer, knowledge points, and similar questions
 * as they are generated by the LLM.
 *
 * SSE event types:
 *   phase     — status transition (routing, solving, grading, done)
 *   step      — a single solution step
 *   answer    — final answer extracted
 *   knowledge — knowledge points
 *   similar   — similar questions
 *   done      — streaming complete, includes metadata
 *   error     — error occurred
 */

import { createLogger } from '@/lib/logger';
import { formatSSE, streamSSE } from '@/lib/assistant/stream';
import { findSimilarQuestions } from '@/lib/solve/question-bank';
import { streamSolve, type StreamEvent } from '@/lib/solve/streaming-solver';
import type { SolverAgentType } from '@/lib/solve/types';
import { generateFourPartOutput } from '@/lib/solve/four-part-output';

const log = createLogger('API:ExplainStream');

// ── Routing (same logic as solve-graph's routeToAgent) ──────────────

function classifyProblem(problemText: string): SolverAgentType {
  const scienceKeywords = ['物理', '化学', '数学', '力学', '微积分', '代数', '几何', '方程', '计算', '求解', '证明'];
  const humanitiesKeywords = ['语文', '历史', '政治', '地理', '文学', '作文', '阅读', '分析', '论述', '谈谈'];

  let scienceScore = 0;
  let humanitiesScore = 0;

  for (const kw of scienceKeywords) {
    if (problemText.includes(kw)) scienceScore++;
  }
  for (const kw of humanitiesKeywords) {
    if (problemText.includes(kw)) humanitiesScore++;
  }

  if (scienceScore > humanitiesScore) return 'science';
  if (humanitiesScore > scienceScore) return 'humanities';
  return 'universal';
}

// ── SSE formatting ──────────────────────────────────────────────────

function formatStreamEvent(event: StreamEvent): string {
  return `data: ${JSON.stringify(event)}\n\n`;
}

function formatSSEEvent(type: string, data: Record<string, unknown> = {}): string {
  return `data: ${JSON.stringify({ type, ...data })}\n\n`;
}

// ── POST handler ────────────────────────────────────────────────────

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { problem, problemImage, userAnswer } = body;

    if (!problem) {
      return new Response(
        formatSSEEvent('error', { message: 'Missing required field: problem' }),
        {
          status: 400,
          headers: { 'Content-Type': 'text/event-stream' },
        },
      );
    }

    log.info(`[ExplainStream] Solving: ${problem.slice(0, 60)}...`);

    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter();
    const encoder = new TextEncoder();

    const write = async (data: string) => {
      await writer.write(encoder.encode(data));
    };

    (async () => {
      try {
        // Phase 1: Check question bank
        await write(formatSSEEvent('phase', { phase: 'checking' }));
        const matches = await findSimilarQuestions(problem, 0.85);

        if (matches.length > 0) {
          const hit = matches[0];
          log.info(`[ExplainStream] Question bank hit (${hit._similarity?.toFixed(2)})`);

          const output = generateFourPartOutput({
            answer: hit.answer,
            steps: [],
            knowledgePoints: [],
            similarQuestions: [],
          });

          await write(formatSSEEvent('step', {
            label: '解答',
            content: hit.answer,
            keyPoints: [],
          }));
          await write(formatSSEEvent('answer', { answer: hit.answer }));
          await write(formatSSEEvent('knowledge', { points: output.knowledgePoints }));
          await write(formatSSEEvent('similar', { questions: output.similarQuestions }));
          await write(formatSSEEvent('done', {
            fromQuestionBank: true,
            solvingTime: 0,
          }));
          await writer.close();
          return;
        }

        // Phase 2: Route to agent
        const agentType = classifyProblem(problem);
        await write(formatSSEEvent('phase', { phase: 'routing', agentType }));

        // Phase 3: Stream solve
        let hasAnswer = false;
        let hasKnowledge = false;
        let hasSimilar = false;

        for await (const event of streamSolve(agentType, problem, problemImage ?? null)) {
          await write(formatStreamEvent(event));
          if (event.type === 'answer') hasAnswer = true;
          if (event.type === 'knowledge') hasKnowledge = true;
          if (event.type === 'similar') hasSimilar = true;
        }

        // Phase 4: Fill in any missing sections
        if (!hasAnswer) {
          await write(formatSSEEvent('answer', { answer: '' }));
        }
        if (!hasKnowledge) {
          await write(formatSSEEvent('knowledge', { points: [] }));
        }
        if (!hasSimilar) {
          await write(formatSSEEvent('similar', { questions: [] }));
        }

        // Phase 5: Done
        const now = Date.now();
        await write(formatSSEEvent('done', {
          fromQuestionBank: false,
          agentType,
        }));

        // Auto-save to question bank (fire-and-forget)
        try {
          const { saveToQuestionBank, isProblemInBank } = await import('@/lib/solve/question-bank');
          const alreadyInBank = await isProblemInBank(problem);
          if (!alreadyInBank) {
            await saveToQuestionBank({
              problemText: problem,
              problemImage: problemImage ?? undefined,
              answer: '',
              steps: [],
              knowledgePoints: [],
              agentId: agentType,
              solvedAt: Date.now(),
              verified: false,
            });
          }
        } catch {
          // ignore save errors
        }

        await writer.close();
      } catch (err) {
        log.error('ExplainStream error:', err);
        try {
          await write(formatSSEEvent('error', {
            message: err instanceof Error ? err.message : '解题失败',
          }));
          await writer.close();
        } catch {
          // already closed
        }
      }
    })();

    return new Response(readable, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    });
  } catch (err) {
    log.error('ExplainStream API error:', err);
    return new Response(
      formatSSEEvent('error', { message: '解题失败' }),
      {
        status: 500,
        headers: { 'Content-Type': 'text/event-stream' },
      },
    );
  }
}
